请对以下 case 进行三维加权评分。

=== case_id ===
Case-15-smart-home-007

=== 用户原始指令 (query.txt) ===
给我做个点一下能进系统设置的智能家居卡片，要有红色危险提示

=== TaskSpec 契约 (task.taskSpec.json) ===
{
  "userQuery": "给我做个点一下能进系统设置的智能家居卡片，要有红色危险提示",
  "size": "2x2",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.hmos.settings",
        "abilityName": "com.huawei.hmos.settings.MainAbility",
        "uri": "intelligent_scene_entry"
      }
    }
  ],
  "dataModelSchema": {
    "home": {
      "title": {
        "type": "string",
        "description": "智能家居卡片的对象标题。",
        "sampleValue": "智能家居"
      },
      "caption": {
        "type": "string",
        "description": "卡片入口或设置场景的简短说明。",
        "sampleValue": "系统入口"
      },
      "primaryStatus": {
        "type": "string",
        "description": "当前智能家居的主要危险状态提示。",
        "sampleValue": "危险"
      },
      "supportText": {
        "type": "string",
        "description": "危险状态下建议用户采取的简短操作提示。",
        "sampleValue": "检查系统设置"
      },
      "actionLabel": {
        "type": "string",
        "description": "进入系统设置的动作标签。",
        "sampleValue": "打开设置"
      }
    }
  },
  "assetCandidates": [
    {
      "src": "resources/base/media/house_fill.svg",
      "description": "房屋实心图标，黑白双色，适合表示智能家居或家庭设置入口。"
    }
  ]
}

